  // ============ Merge ============
  public static ServicesConfig.Services.Builder mergeServices(
      ServicesConfig.Services dst, ServicesConfig.Services src) {
    ServicesConfig.Services.Builder builder = dst.toBuilder();
    if (!dst.hasSentinelConfig() && src.hasSentinelConfig()) {
      builder.setSentinelConfig(src.getSentinelConfig());
    }
    if (!dst.hasOauthConfig() && src.hasOauthConfig()) {
      builder.setOauthConfig(src.getOauthConfig());
    }
    if (!dst.hasGatewayConfig() && src.hasGatewayConfig()) {
      builder.setGatewayConfig(src.getGatewayConfig());
    }
    if (!dst.hasLetsencryptConfig() && src.hasLetsencryptConfig()) {
      builder.setLetsencryptConfig(src.getLetsencryptConfig());
    }
    if (!dst.hasMcpConfig() && src.hasMcpConfig()) {
      builder.setMcpConfig(src.getMcpConfig());
    }
    if (!dst.hasDgraphConfig() && src.hasDgraphConfig()) {
      builder.setDgraphConfig(src.getDgraphConfig());
    }
    if (!dst.hasAegisConfig() && src.hasAegisConfig()) {
      builder.setAegisConfig(src.getAegisConfig());
    }
    if (!dst.hasEventbusConfig() && src.hasEventbusConfig()) {
      builder.setEventbusConfig(src.getEventbusConfig());
    }
    if (!dst.hasBigdataConfig() && src.hasBigdataConfig()) {
      builder.setBigdataConfig(src.getBigdataConfig());
    }
    if (!dst.hasClickhouseConfig() && src.hasClickhouseConfig()) {
      builder.setClickhouseConfig(src.getClickhouseConfig());
    }
    if (!dst.hasFleetwoodConfig() && src.hasFleetwoodConfig()) {
      builder.setFleetwoodConfig(src.getFleetwoodConfig());
    }
    if (!dst.hasAnthropicConfig() && src.hasAnthropicConfig()) {
      builder.setAnthropicConfig(src.getAnthropicConfig());
    }
    if (!dst.hasGithubConfig() && src.hasGithubConfig()) {
      builder.setGithubConfig(src.getGithubConfig());
    }
    if (!dst.hasGitlabConfig() && src.hasGitlabConfig()) {
      builder.setGitlabConfig(src.getGitlabConfig());
    }
    return builder;
  }

